/*
Kernels for the AdamW optimizer.

References:
  * https://pytorch.org/docs/stable/generated/torch.optim.AdamW.html
  * https://github.com/nvidia/apex/blob/master/csrc/multi_tensor_adam.cu

Compile example:
nvcc -lcublas -lcublasLt adamw.cu -o adamw
nvcc -O3 --use_fast_math -lcublas -lcublasLt adamw.cu -o adamw

./adamw

TODO(general):
amsgrad=True

TODO(perf):
dtype
thread coarsening/ILP
*/

#define DPCT_PROFILING_ENABLED
#include <sycl/sycl.hpp>
#include <dpct/dpct.hpp>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include "common.h"
#include <cmath>

// ----------------------------------------------------------------------------
// CPU code reference

// museport: CPU reference adamw_cpu() removed (it is the hidden check)

// ----------------------------------------------------------------------------
// GPU kernels

// utility functions

// Implements linear interpolation using only two floating-point operations (as opposed to three in a naive implementation).
// Reference: https://developer.nvidia.com/blog/lerp-faster-cuda
inline float lerp(float start, float end, float weight) {
    return sycl::fma(weight, end, sycl::fma(-weight, start, start));
}

// naive fused kernel
void adamw_kernel1(float* params_memory, const float* grads_memory, float* m_memory, float* v_memory, long num_parameters,
                              float learning_rate, float beta1, float beta2, float beta1_correction, float beta2_correction, float eps, float weight_decay) {
   auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
   int i = item_ct1.get_group(2) * item_ct1.get_local_range(2) +
           item_ct1.get_local_id(2);
   if (i >= num_parameters) return;  // guard
   // update the first moment (momentum)
   m_memory[i] = beta1 * m_memory[i] + (1.0f - beta1) * grads_memory[i];
   // update the second moment (RMSprop)
   v_memory[i] = beta2 * v_memory[i] + (1.0f - beta2) * grads_memory[i] * grads_memory[i];
   float m_hat = m_memory[i] / beta1_correction;
   float v_hat = v_memory[i] / beta2_correction;
   params_memory[i] -= learning_rate * (m_hat / (sycl::sqrt(v_hat) + eps) +
                                        weight_decay * params_memory[i]);
}

// Slightly more optimized AdamW kernel by:
// * loading data that is accessed more than once into registers,
// * using optimized linear interpolation for the moment updates.
void adamw_kernel2(float* params_memory, const float* grads_memory, float* m_memory, float* v_memory, long num_parameters,
                              float learning_rate, float beta1, float beta2, float beta1_correction, float beta2_correction, float eps, float weight_decay) {
   auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
   int i = item_ct1.get_group(2) * item_ct1.get_local_range(2) +
           item_ct1.get_local_id(2);
   if (i >= num_parameters) return;  // guard
   float grad = grads_memory[i];
   float m = m_memory[i];
   float v = v_memory[i];
   // update the first moment (momentum)
   m = lerp(grad, m, beta1);
   m_memory[i] = m;
   // update the second moment (RMSprop)
   v = lerp(grad * grad, v, beta2);
   v_memory[i] = v;
   m /= beta1_correction;  // m_hat
   v /= beta2_correction;  // v_hat
   params_memory[i] -= learning_rate * (m / (sycl::sqrt(v) + eps) +
                                        weight_decay * params_memory[i]);
}


// ----------------------------------------------------------------------------
// kernel launcher

// version 1: naive dispatch to naive kernel
void adamw_dispatch1(float* params_memory, const float* grads_memory, float* m_memory, float* v_memory, long num_parameters,
                     float learning_rate, float beta1, float beta2, float beta1_correction, float beta2_correction, float eps, float weight_decay) {
    unsigned int block_size = 512;
    unsigned int num_blocks = ceil_div(num_parameters, (long) block_size);
    /*
    DPCT1049:1: The work-group size passed to the SYCL kernel may exceed the
    limit. To get the device limit, query info::device::max_work_group_size.
    Adjust the work-group size if needed.
    */
    dpct::get_in_order_queue().parallel_for(
        sycl::nd_range<3>(sycl::range<3>(1, 1, num_blocks) *
                              sycl::range<3>(1, 1, block_size),
                          sycl::range<3>(1, 1, block_size)),
        [=](sycl::nd_item<3> item_ct1) {
            adamw_kernel1(params_memory, grads_memory, m_memory, v_memory,
                          num_parameters, learning_rate, beta1, beta2,
                          beta1_correction, beta2_correction, eps,
                          weight_decay);
        });
    /*
    DPCT1010:17: SYCL uses exceptions to report errors and does not use the
    error codes. The cudaGetLastError function call was replaced with 0. You
    need to rewrite this code.
    */
    cudaCheck(0);
}

// version 2: naive dispatch to slightly optimized kernel
void adamw_dispatch2(float* params_memory, const float* grads_memory, float* m_memory, float* v_memory, long num_parameters,
                     float learning_rate, float beta1, float beta2, float beta1_correction, float beta2_correction, float eps, float weight_decay) {
    unsigned int block_size = 512;
    unsigned int num_blocks = ceil_div(num_parameters, (long) block_size);
    /*
    DPCT1049:2: The work-group size passed to the SYCL kernel may exceed the
    limit. To get the device limit, query info::device::max_work_group_size.
    Adjust the work-group size if needed.
    */
    dpct::get_in_order_queue().parallel_for(
        sycl::nd_range<3>(sycl::range<3>(1, 1, num_blocks) *
                              sycl::range<3>(1, 1, block_size),
                          sycl::range<3>(1, 1, block_size)),
        [=](sycl::nd_item<3> item_ct1) {
            adamw_kernel2(params_memory, grads_memory, m_memory, v_memory,
                          num_parameters, learning_rate, beta1, beta2,
                          beta1_correction, beta2_correction, eps,
                          weight_decay);
        });
    /*
    DPCT1010:18: SYCL uses exceptions to report errors and does not use the
    error codes. The cudaGetLastError function call was replaced with 0. You
    need to rewrite this code.
    */
    cudaCheck(0);
}

void adamw(int kernel_num,
           float* params_memory, const float* grads_memory, float* m_memory, float* v_memory, int t, long num_parameters,
           float learning_rate=1e-3, float beta1=0.9, float beta2=0.999, float eps=1e-8, float weight_decay=0.0) {
    // calculate the m_hat and v_hat correction terms once as they are the same for every param/thread
    float beta1_correction = 1.0f - powf(beta1, t);
    float beta2_correction = 1.0f - powf(beta2, t);
    switch (kernel_num) {
        case 1:
            adamw_dispatch1(params_memory, grads_memory, m_memory, v_memory, num_parameters,
                            learning_rate, beta1, beta2, beta1_correction, beta2_correction, eps, weight_decay);
            break;
        case 2:
            adamw_dispatch2(params_memory, grads_memory, m_memory, v_memory, num_parameters,
                            learning_rate, beta1, beta2, beta1_correction, beta2_correction, eps, weight_decay);
            break;
        default:
            printf("Invalid kernel number\n");
            exit(1);
    }
}

// ----------------------------------------------------------------------------

// ----------------------------------------------------------------------------
// museport contract main: <input> <output> sizes...; runs every kernel variant and
// writes each variant's outputs, in order, as raw float32.
int main(int argc, char** argv) {
    setup_main();
    if (argc != 4) {
        fprintf(stderr, "usage: %s <input> <output> N\n", argv[0]);
        return 2;
    }
    const int N = atoi(argv[3]);
    FILE* fin = fopen(argv[1], "rb");
    if (!fin) { perror(argv[1]); return 2; }
    float* params = (float*)malloc(sizeof(float) * (size_t)(N));
    if (fread(params, sizeof(float), (size_t)(N), fin) != (size_t)(N)) {
        fprintf(stderr, "input too short at params\n"); return 2;
    }
    float* grads = (float*)malloc(sizeof(float) * (size_t)(N));
    if (fread(grads, sizeof(float), (size_t)(N), fin) != (size_t)(N)) {
        fprintf(stderr, "input too short at grads\n"); return 2;
    }
    float* m = (float*)malloc(sizeof(float) * (size_t)(N));
    if (fread(m, sizeof(float), (size_t)(N), fin) != (size_t)(N)) {
        fprintf(stderr, "input too short at m\n"); return 2;
    }
    float* v = (float*)malloc(sizeof(float) * (size_t)(N));
    if (fread(v, sizeof(float), (size_t)(N), fin) != (size_t)(N)) {
        fprintf(stderr, "input too short at v\n"); return 2;
    }
    fclose(fin);
    FILE* fout = fopen(argv[2], "wb");
    if (!fout) { perror(argv[2]); return 2; }
    float* d_params;
    cudaCheck(DPCT_CHECK_ERROR(d_params = sycl::malloc_device<float>(
                                   (size_t)(N), dpct::get_in_order_queue())));
    cudaCheck(DPCT_CHECK_ERROR(
        dpct::get_in_order_queue()
            .memcpy(d_params, params, sizeof(float) * (size_t)(N))
            .wait()));
    float* d_grads;
    cudaCheck(DPCT_CHECK_ERROR(d_grads = sycl::malloc_device<float>(
                                   (size_t)(N), dpct::get_in_order_queue())));
    cudaCheck(DPCT_CHECK_ERROR(
        dpct::get_in_order_queue()
            .memcpy(d_grads, grads, sizeof(float) * (size_t)(N))
            .wait()));
    float* d_m;
    cudaCheck(DPCT_CHECK_ERROR(d_m = sycl::malloc_device<float>(
                                   (size_t)(N), dpct::get_in_order_queue())));
    cudaCheck(DPCT_CHECK_ERROR(dpct::get_in_order_queue()
                                   .memcpy(d_m, m, sizeof(float) * (size_t)(N))
                                   .wait()));
    float* d_v;
    cudaCheck(DPCT_CHECK_ERROR(d_v = sycl::malloc_device<float>(
                                   (size_t)(N), dpct::get_in_order_queue())));
    cudaCheck(DPCT_CHECK_ERROR(dpct::get_in_order_queue()
                                   .memcpy(d_v, v, sizeof(float) * (size_t)(N))
                                   .wait()));
    float* params_out = (float*)malloc(sizeof(float) * (size_t)(N));
    float* d_params_out;
    cudaCheck(DPCT_CHECK_ERROR(d_params_out = sycl::malloc_device<float>(
                                   (size_t)(N), dpct::get_in_order_queue())));
    float* m_out = (float*)malloc(sizeof(float) * (size_t)(N));
    float* d_m_out;
    cudaCheck(DPCT_CHECK_ERROR(d_m_out = sycl::malloc_device<float>(
                                   (size_t)(N), dpct::get_in_order_queue())));
    float* v_out = (float*)malloc(sizeof(float) * (size_t)(N));
    float* d_v_out;
    cudaCheck(DPCT_CHECK_ERROR(d_v_out = sycl::malloc_device<float>(
                                   (size_t)(N), dpct::get_in_order_queue())));
    const int variants[] = {1, 2};
    for (int vi = 0; vi < 2; vi++) {
        const int k = variants[vi];
        cudaCheck(DPCT_CHECK_ERROR(
            dpct::get_in_order_queue()
                .memcpy(d_params_out, params, sizeof(float) * (size_t)(N))
                .wait()));
        cudaCheck(DPCT_CHECK_ERROR(
            dpct::get_in_order_queue()
                .memcpy(d_m_out, m, sizeof(float) * (size_t)(N))
                .wait()));
        cudaCheck(DPCT_CHECK_ERROR(
            dpct::get_in_order_queue()
                .memcpy(d_v_out, v, sizeof(float) * (size_t)(N))
                .wait()));
        adamw(k, d_params_out, d_grads, d_m_out, d_v_out, 10, N);
        /*
        DPCT1010:19: SYCL uses exceptions to report errors and does not use the
        error codes. The cudaGetLastError function call was replaced with 0. You
        need to rewrite this code.
        */
        cudaCheck(0);
        cudaCheck(DPCT_CHECK_ERROR(
            dpct::get_current_device().queues_wait_and_throw()));
        cudaCheck(DPCT_CHECK_ERROR(
            dpct::get_in_order_queue()
                .memcpy(params_out, d_params_out, sizeof(float) * (size_t)(N))
                .wait()));
        fwrite(params_out, sizeof(float), (size_t)(N), fout);
        cudaCheck(DPCT_CHECK_ERROR(
            dpct::get_in_order_queue()
                .memcpy(m_out, d_m_out, sizeof(float) * (size_t)(N))
                .wait()));
        fwrite(m_out, sizeof(float), (size_t)(N), fout);
        cudaCheck(DPCT_CHECK_ERROR(
            dpct::get_in_order_queue()
                .memcpy(v_out, d_v_out, sizeof(float) * (size_t)(N))
                .wait()));
        fwrite(v_out, sizeof(float), (size_t)(N), fout);
    }
    fclose(fout);
    return 0;
}

#define DPCT_COMPAT_RT_MAJOR_VERSION 12
#define DPCT_PROFILING_ENABLED
#include <sycl/sycl.hpp>
#include <dpct/dpct.hpp>
#include <stdlib.h>
#include <stdio.h>
#include <float.h>
#include <cmath>

#define WARP_SIZE 32U
extern dpct::device_info deviceProp;

template<class T>
T ceil_div(T dividend, T divisor) {
    return (dividend + divisor-1) / divisor;
}

float warpReduceSum(float val) {
    for (int offset = 16; offset > 0; offset /= 2) {
        val += dpct::permute_sub_group_by_xor(
            sycl::ext::oneapi::this_work_item::get_sub_group(), val, offset);
    }
    return val;
}

// requires all 32 threads in the warp to be active, but should work for any block size
// uses non-dynamic shared memory so every call increases shared memory requirements by 128 bytes
// the fact it's unique shared memory allows us to avoid an extra __syncthreads() call at the end
// but if called inside a loop, the shared memory will be implicitly reused, so set final_sync to 1
using reduction_func_t = float (*) (float);

template<reduction_func_t warp_reduction>
inline float blockReduce(float val, bool final_sync, float out_of_bounds,
                         float *shared_val) {
    // two reductions of up to 1024 threads:
    // 1) inside warp (shuffle), 2) cross-warp (shared memory), 3) inside warp (shuffle)
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();

    const int lane_id = item_ct1.get_local_id(2) % WARP_SIZE;
    const int warp_id = item_ct1.get_local_id(2) / WARP_SIZE;
    const int num_warps = item_ct1.get_local_range(2) / WARP_SIZE;

    float warp_val = warp_reduction(val);
    if (lane_id == 0) { shared_val[warp_id] = warp_val; }
    /*
    DPCT1065:3: Consider replacing sycl::nd_item::barrier() with
    sycl::nd_item::barrier(sycl::access::fence_space::local_space) for better
    performance if there is no access to global memory.
    */
    item_ct1.barrier();
    warp_val = (lane_id < num_warps) ? shared_val[lane_id] : out_of_bounds;
    float block_val = warp_reduction(warp_val);

    if (final_sync) {
        /*
        DPCT1118:0: SYCL group functions and algorithms must be encountered in
        converged control flow. You may need to adjust the code.
        */
        /*
        DPCT1065:4: Consider replacing sycl::nd_item::barrier() with
        sycl::nd_item::barrier(sycl::access::fence_space::local_space) for
        better performance if there is no access to global memory.
        */
        item_ct1.barrier(); // only needed in loops when effectively reusing
                            // shared memory etc.
    }
    return block_val;
}

// Helper function to call blockReduce with default arguments
template<reduction_func_t warp_reduction>
inline float blockReduce(float val, float *shared_val) {
    return blockReduce<warp_reduction>(val, false, 0.0f, shared_val);
}

